'use strict';

/* Cipher League: self-contained simulated fantasy cybersecurity game.
   All scores, players, and security events are fictional. Nothing here reads real incidents. */

const VERSION = 1;
const STORAGE_KEY = 'cipher-league-save-v1';
const ROLES = ['soc', 'red', 'dfir', 'intel', 'eng'];
const SLOTS = ['soc', 'red', 'dfir', 'intel', 'eng', 'flex'];
const ROLE_INFO = {
  soc: { short:'SOC', name:'SOC Analyst', color:'#8bc2ff', symbol:'◎', activity:'Confirmed detections' },
  red: { short:'RED', name:'Red Teamer', color:'#ff929d', symbol:'⌁', activity:'Validated findings' },
  dfir:{ short:'DFIR', name:'Incident Responder', color:'#bda7ff', symbol:'◇', activity:'Incidents contained' },
  intel:{ short:'INTEL', name:'Threat Intel', color:'#ffd18e', symbol:'✳', activity:'Actionable reports' },
  eng: { short:'ENG', name:'Security Engineer', color:'#90e2b5', symbol:'▣', activity:'Hardening fixes' },
  flex:{ short:'FLEX', name:'Flex Operator', color:'#c2d1e1', symbol:'+' }
};
const TEAM_NAMES = ['Ghost Protocol','Packet Pirates','Null Pointers','Zero-Day Saints','Kernel Panic','Blue Screen Crew','APT Anonymous','Root Access'];
const TEAM_COLORS = ['#81b77d','#8c80ca','#5d9fb8','#c78f75','#be8a9a','#c0a46a','#71a9b1','#848bd0'];
const FIRST_NAMES = ['Nova','Kira','Milo','Aria','Jace','Zara','Orion','Sage','Niko','Maya','Axel','Iris','Rohan','Lena','Kai','Cleo','Ezra','Talia','Finn','Uma','Theo','Ayla','Rin','Dante','Remy','Juno','Asher','Veda','Leo','Mina','Quinn','Sora'];
const LAST_NAMES = ['Chen','Vega','Park','Mercer','Ibrahim','Kade','Okafor','Sato','Reyes','Blake','Patel','Nyx','Costa','Ito','Stone','Hale','Singh','Frost','Morgan','Vale','Kim','Arden','Lin','Rivera','Brooks','Shah','Dawson','Roan','Beck','Khan','Wells','Cross'];
const HANDLES = ['hex','cipher','ghost','byte','stack','zero','patch','neon','node','vault','proxy','sable','flux','kernel','orbit','delta','quartz','cobalt','pulse','vector','signal','sparrow','omega','atlas','shadow','ember','echo','matrix','pixel','root','glitch','sentry'];
const ORGS = ['Northstar Sec','Vector Labs','Nightwatch','Fortress One','Cyber Arc','Tracepoint','Aegis Systems','GreyMatter'];
const PLAYER_POOL = Array.from({length:100},(_,i)=>{
  const role = ROLES[(i*7 + Math.floor(i/20)) % 5];
  const rating = 72 + (hashInt('rating:'+i) % 27);
  return {id:i+1,name:`${FIRST_NAMES[i%32]} ${LAST_NAMES[(i*13+Math.floor(i/32)*7)%32]}`,handle:'@'+HANDLES[i%32]+String(10+(i*19)%89),role,org:ORGS[(i*3)%ORGS.length],rating,trend:(hashInt('trend:'+i)%17)-7};
});
const PLAYER_BY_ID = Object.fromEntries(PLAYER_POOL.map(p=>[p.id,p]));
const ICON_PATHS = {
  overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/>',
  roster:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',
  draft:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 10h18M9 4v16M15 10v10"/>',
  matchups:'<path d="M8 21V7M16 21V7M4 7h16M6 3h12M8 13l4-3 4 3M8 21h8"/>',
  leaderboard:'<path d="M8 21V9l-4 2V21M16 21V3l-4 2v16M24 21v-8l-4 2v6"/>',
  market:'<circle cx="12" cy="12" r="9"/><path d="M12 6v12M8.5 9.5a3.5 3.5 0 0 1 7 0c0 3-7 2-7 5a3.5 3.5 0 0 0 7 0"/>',
  howto:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 4.6 1.4c-.8 1-2.1 1.5-2.1 3.1M12 17.4v.2"/>',
  settings:'<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.87l.06.06-1.8 1.8-.07-.06a1.7 1.7 0 0 0-1.86-.35 1.7 1.7 0 0 0-1 1.56V20h-2.5v-.1a1.7 1.7 0 0 0-1.06-1.57 1.7 1.7 0 0 0-1.86.35l-.07.06-1.8-1.8.06-.06A1.7 1.7 0 0 0 8.2 15a1.7 1.7 0 0 0-1.57-1H6.5v-2.5h.12a1.7 1.7 0 0 0 1.57-1.06 1.7 1.7 0 0 0-.35-1.86l-.06-.07 1.8-1.8.07.06a1.7 1.7 0 0 0 1.86.35 1.7 1.7 0 0 0 1.06-1.57V5.5h2.5v.12a1.7 1.7 0 0 0 1.06 1.57 1.7 1.7 0 0 0 1.86-.35l.07-.06 1.8 1.8-.06.07a1.7 1.7 0 0 0-.35 1.86 1.7 1.7 0 0 0 1.57 1.06h.12v2.5h-.12A1.7 1.7 0 0 0 19.4 15Z" transform="translate(-1.5 -1.5) scale(1.08)"/>',
  arrow:'<path d="M5 12h14m-7-7 7 7-7 7"/>',
  chart:'<path d="M3 3v18h18M7 15l5-6 4 3 5-7"/>',
  bolt:'<path d="m13 2-9 12h7l-1 8 10-12h-7z"/>',
  trophy:'<path d="M8 21h8M12 17v4M7 3h10v7a5 5 0 0 1-10 0V3ZM7 5H3v3a4 4 0 0 0 4 4M17 5h4v3a4 4 0 0 1-4 4"/>',
  target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
  shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/>'
};
function icon(type){return `<svg viewBox="0 0 24 24" width="18" height="18" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" fill="none" aria-hidden="true">${ICON_PATHS[type]||ICON_PATHS.shield}</svg>`;}
function hashInt(v){let h=2166136261;for(let i=0;i<v.length;i++){h^=v.charCodeAt(i);h=Math.imul(h,16777619);}return h>>>0;}
function seeded(seed){let n=hashInt(String(seed));return ()=>{n+=0x6D2B79F5;let t=n;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return ((t^t>>>14)>>>0)/4294967296;};}
function rand(r,a,b){return a+Math.floor(r()*(b-a+1));}
function escapeHTML(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function fmt(v){return Number(v||0).toFixed(1);}
function team(id){return game.teams[id];}
function userTeam(){return game.teams[0];}
function player(id){return PLAYER_BY_ID[id];}
function initials(name){return name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]?.toUpperCase()).join('')||'CL';}
function avatar(p,size){let colors={soc:'#284765',red:'#673a4b',dfir:'#52476d',intel:'#675337',eng:'#2b5a50'};return `<span class="player-avatar" style="background:${colors[p.role]}">${initials(p.name)}</span>`;}
function emblem(t,small=false){return `<span class="${small?'row-avatar':'team-emblem'}" style="background:${t.color}24;color:${t.color};border-color:${t.color}55">${initials(t.name)}</span>`;}
function scoreDetails(id,week){
  const p=player(id);if(!p)return {points:0,events:[],stats:{}};
  const r=seeded(`score:${id}:${week}:CL1`);const quality=p.rating;const bonus=Math.floor((quality-70)/12);
  let stats={}, events=[], points=0;
  if(p.role==='soc'){
    stats={detections:rand(r,1,3)+bonus,hunts:rand(r,0,3),falsePositives:rand(r,0,2)};
    events=[['Confirmed detections',stats.detections,6],['Proactive hunts',stats.hunts,4],['False positives',stats.falsePositives,-2]];
  }else if(p.role==='red'){
    stats={findings:rand(r,1,3)+Math.floor(bonus/2),criticals:rand(r,0,2),reports:rand(r,0,2)};
    events=[['Validated findings',stats.findings,7],['Critical discoveries',stats.criticals,10],['Quality write-ups',stats.reports,3]];
  }else if(p.role==='dfir'){
    stats={contained:rand(r,1,2)+Math.floor(bonus/2),recoveries:rand(r,1,4),breaches:rand(r,0,1)};
    events=[['Incidents contained',stats.contained,8],['Recovery actions',stats.recoveries,4],['Missed containment',stats.breaches,-6]];
  }else if(p.role==='intel'){
    stats={intel:rand(r,2,4)+Math.floor(bonus/2),iocs:rand(r,1,6),briefs:rand(r,0,3)};
    events=[['Actionable reports',stats.intel,5],['Verified indicators',stats.iocs,2],['Threat briefs',stats.briefs,3]];
  }else{
    stats={fixes:rand(r,2,5)+bonus,patches:rand(r,0,2),rollbacks:rand(r,0,1)};
    events=[['Hardening fixes',stats.fixes,4],['Critical patches',stats.patches,6],['Failed changes',stats.rollbacks,-3]];
  }
  points=events.reduce((acc,[,quantity,each])=>acc+quantity*each,0);
  return {points:Math.max(0,points),events,stats};
}
function projection(id,week){if(!id)return 0;const p=player(id);const r=seeded(`projection:${id}:${week}`);const weight={soc:1,red:.95,dfir:.91,intel:.88,eng:1}[p.role];return Math.round((12+p.rating*.18+rand(r,-6,6))*weight*10)/10;}
function validForSlot(id,slot){return !!id&&(slot==='flex'||player(id)?.role===slot);}
function assignLineup(ids){const sorted=[...ids].sort((a,b)=>player(b).rating-player(a).rating);const chosen={};for(const slot of ROLES){chosen[slot]=sorted.find(id=>player(id).role===slot&&!Object.values(chosen).includes(id))||null;}chosen.flex=sorted.find(id=>!Object.values(chosen).includes(id))||null;return chosen;}
function pickFromPool(used,role,offset=0){const available=PLAYER_POOL.filter(p=>!used.has(p.id)&&(!role||p.role===role)).sort((a,b)=>b.rating-a.rating||a.id-b.id);const p=available[Math.min(offset,Math.max(0,available.length-1))];if(!p)return null;used.add(p.id);return p.id;}
function freshTeams(){return TEAM_NAMES.map((name,i)=>({id:i,name,manager:i===0?'You':['','ByteMaster','StackQueen','ZeroCool','ShellShock','BlueGhost','Phantom','PacketKing'][i],color:TEAM_COLORS[i],roster:[],lineup:{}}));}
function freshGame(){
  const teams=freshTeams();const used=new Set();
  // Each team starts with one specialist in every core role, a flex and two reserves.
  for(const role of ROLES)for(let t=0;t<8;t++)teams[t].roster.push(pickFromPool(used,role,t%3));
  for(let t=0;t<8;t++)teams[t].roster.push(pickFromPool(used,null,t%4));
  for(let round=0;round<2;round++)for(let t=0;t<8;t++)teams[t].roster.push(pickFromPool(used,null,(t+round)%5));
  teams.forEach(t=>t.lineup=assignLineup(t.roster));
  return {version:VERSION,teams,week:1,results:{},lastSimulatedWeek:0,lastEvents:[],draft:{active:false,complete:true,pick:0,picks:[]}};
}
function loadGame(){try{const x=JSON.parse(localStorage.getItem(STORAGE_KEY));if(validateSave(x))return x;}catch(e){/* fall back to new season */}return freshGame();}
function validateSave(x){
  if(!x||x.version!==VERSION||!Array.isArray(x.teams)||x.teams.length!==8||!Number.isInteger(x.week)||x.week<1||x.week>10||!x.results||typeof x.results!=='object'||!x.draft||typeof x.draft.active!=='boolean'||!Number.isInteger(x.draft.pick)||x.draft.pick<0||x.draft.pick>64||!Array.isArray(x.draft.picks)||x.draft.picks.length>64||!Array.isArray(x.lastEvents)||!Number.isInteger(x.lastSimulatedWeek)||x.lastSimulatedWeek<0||x.lastSimulatedWeek>9)return false;
  const all=[];
  for(let i=0;i<8;i++){
    const t=x.teams[i];
    if(!t||t.id!==i||typeof t.name!=='string'||t.name.length<1||t.name.length>26||typeof t.manager!=='string'||t.manager.length>45||typeof t.color!=='string'||!/^#[0-9a-fA-F]{6}$/.test(t.color)||!Array.isArray(t.roster)||t.roster.length>8||!t.lineup||typeof t.lineup!=='object')return false;
    if(!t.roster.every(id=>Number.isInteger(id)&&!!player(id)))return false;
    for(const slot of SLOTS){const id=t.lineup[slot];if(id!==null&&id!==undefined&&(!Number.isInteger(id)||!t.roster.includes(id)))return false;}
    const starters=SLOTS.map(s=>t.lineup[s]).filter(Boolean);if(new Set(starters).size!==starters.length)return false;
    all.push(...t.roster);
  }
  if(new Set(all).size!==all.length)return false;
  for(const [w,rounds] of Object.entries(x.results)){
    if(!/^([1-9])$/.test(w)||!Array.isArray(rounds)||rounds.length!==(Number(w)<=7?4:2))return false;
    if(!rounds.every(r=>r&&Number.isInteger(r.a)&&Number.isInteger(r.b)&&r.a>=0&&r.a<8&&r.b>=0&&r.b<8&&r.a!==r.b&&Number.isFinite(r.scoreA)&&r.scoreA>=0&&Number.isFinite(r.scoreB)&&r.scoreB>=0))return false;
  }
  return true;
}
let game=loadGame();let view='overview';let selectedWeek=1;let marketRole='all';let marketSort='rating';let marketQuery='';
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(game));}catch(e){toast('Your browser is blocking local saves. Export your progress in Settings.',true);}}
function availablePlayers(){const used=new Set(game.teams.flatMap(t=>t.roster));return PLAYER_POOL.filter(p=>!used.has(p.id));}
function roundRobin(week){let a=Array.from({length:8},(_,i)=>i);for(let k=1;k<week;k++)a=[a[0],a[7],...a.slice(1,7)];return Array.from({length:4},(_,i)=>[a[i],a[7-i]]);}
function leagueTable(){let table=game.teams.map(t=>({id:t.id,wins:0,losses:0,pf:0,pa:0}));for(let w=1;w<=7;w++){for(const r of game.results[w]||[]){const a=table[r.a],b=table[r.b];a.pf+=r.scoreA;a.pa+=r.scoreB;b.pf+=r.scoreB;b.pa+=r.scoreA;if(r.scoreA===r.scoreB){if(r.a<r.b)a.wins++,b.losses++;else b.wins++,a.losses++;}else if(r.scoreA>r.scoreB)a.wins++,b.losses++;else b.wins++,a.losses++;}}return table.sort((a,b)=>b.wins-a.wins||b.pf-a.pf||a.id-b.id);}
function getPairs(week){if(week<=7)return roundRobin(week);if(week===8){if(!game.results[7])return [];let ranked=leagueTable().map(t=>t.id);return [[ranked[0],ranked[3]],[ranked[1],ranked[2]]];}if(week===9){if(!game.results[8])return [];const semi=game.results[8];return [[winnerId(semi[0]),winnerId(semi[1])],[loserId(semi[0]),loserId(semi[1])]];}return [];}
function winnerId(r){return r.scoreA>=r.scoreB?r.a:r.b;}
function loserId(r){return r.scoreA>=r.scoreB?r.b:r.a;}
function teamScore(t,week,actual=false){return Math.round(SLOTS.reduce((sum,slot)=>{const pid=t.lineup[slot];return sum+(pid?(actual?scoreDetails(pid,week).points:projection(pid,week)):0);},0)*10)/10;}
function matchForTeam(week,tid){const result=(game.results[week]||[]).find(r=>r.a===tid||r.b===tid);if(result)return {a:result.a,b:result.b,scoreA:result.scoreA,scoreB:result.scoreB,final:true};const pair=getPairs(week).find(pair=>pair.includes(tid));if(!pair)return null;return {a:pair[0],b:pair[1],scoreA:teamScore(team(pair[0]),week),scoreB:teamScore(team(pair[1]),week),final:false};}
function weekName(w){if(w===8)return 'SEMIFINALS';if(w===9)return 'CHAMPIONSHIP';if(w>=10)return 'SEASON COMPLETE';return `WEEK ${String(w).padStart(2,'0')}`;}
function currentWeek(){return Math.min(game.week,9);}
function shortRole(role){return ROLE_INFO[role]?.short||role.toUpperCase();}
function ranking(id){return leagueTable().findIndex(t=>t.id===id)+1;}
function scoringEvents(week){const events=[];for(const t of game.teams){for(const id of Object.values(t.lineup)){if(!id)continue;let d=scoreDetails(id,week);events.push({id,t:t.id,points:d.points,top:d.events.filter(e=>e[1]>0).sort((a,b)=>b[1]*b[2]-a[1]*a[2])[0]});}}return events.sort((a,b)=>b.points-a.points).slice(0,6);}
function playWeek(){
  if(game.draft.active)return toast('Finish the draft before starting the season.',true);
  if(game.week>9)return toast('The season is already complete.',true);
  const week=game.week;const pairs=getPairs(week);
  if(!pairs.length)return toast('Playoff matchups are not ready yet.',true);
  game.results[week]=pairs.map(([a,b])=>({a,b,scoreA:teamScore(team(a),week,true),scoreB:teamScore(team(b),week,true)}));
  game.lastEvents=scoringEvents(week);game.lastSimulatedWeek=week;game.week++;
  selectedWeek=week;
  save();render();
  if(week===9){const champ=winnerId(game.results[9][0]);toast(`${team(champ).name} takes the Cipher League championship!`);}else toast(`${weekName(week)} complete. Scores and standings updated.`);
}
const NAV=[['overview','Overview'],['roster','My Roster'],['draft','Draft Room'],['matchups','Matchups'],['leaderboard','Leaderboard'],['market','Free Agents'],['howto','How to Play'],['settings','Settings']];
function renderNav(){document.getElementById('side-nav').innerHTML=NAV.map(([id,label])=>`<button class="nav-link ${view===id?'active':''}" data-view="${id}"><span class="nav-icon">${icon(id)}</span><span>${label}</span>${id==='draft'&&game.draft.active?'<span class="nav-tag">LIVE</span>':''}</button>`).join('');}
function render(){
  renderNav();document.getElementById('crumb-current').textContent=(NAV.find(x=>x[0]===view)?.[1]||'OVERVIEW').toUpperCase();
  document.getElementById('header-week').innerHTML=`${weekName(game.week)} <span>▼</span>`;
  document.getElementById('profile-team').textContent=userTeam().name;
  document.querySelectorAll('.topbar-avatar,.profile-avatar').forEach(x=>x.textContent=initials(userTeam().name));
  const renderers={overview:renderOverview,roster:renderRoster,draft:renderDraft,matchups:renderMatchups,leaderboard:renderLeaderboard,market:renderMarket,howto:renderHowto,settings:renderSettings};
  document.getElementById('main-view').innerHTML=(renderers[view]||renderOverview)();
}
function navigate(id){if(!NAV.find(n=>n[0]===id))id='overview';view=id;location.hash=id;marketQuery='';marketRole='all';marketSort='rating';selectedWeek=currentWeek();render();window.scrollTo({top:0,behavior:'instant'});closeNav();}
function closeNav(){document.getElementById('sidebar').classList.remove('is-open');document.getElementById('mobile-scrim').classList.remove('is-open');}
function heading(eyebrow,title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="page-intro">${description}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`;}
function statCard(label,value,foot,ic,accentColor=''){return `<div class="stat-card"><div class="stat-icon">${icon(ic)}</div><div class="stat-label">${label}</div><div class="stat-value" ${accentColor?`style="color:${accentColor}"`:''}>${value}</div><div class="stat-foot">${foot}</div></div>`;}
function miniTeam(t){return `<div class="mini-team">${emblem(t,true)}<div><strong>${escapeHTML(t.name)}</strong><small>${t.id===0?'YOUR TEAM':escapeHTML(t.manager)}</small></div></div>`;}
function matchupPanel(m){
  if(!m)return `<div class="panel"><div class="empty-state"><div class="empty-graphic">◇</div>Playoff bracket locks after the regular season.</div></div>`;
  const a=team(m.a),b=team(m.b);let lhs=m.scoreA,rhs=m.scoreB,ratio=lhs+rhs?lhs/(lhs+rhs)*100:50;
  const winner=m.final?(lhs>=rhs?m.a:m.b):null;
  return `<div class="panel matchup-panel"><div class="panel-header"><div><strong>${m.final?'FINAL SCORE':'THIS WEEK\'S MATCHUP'}</strong><span class="subline">${weekName(m.final?game.lastSimulatedWeek:game.week)} · ${m.final?'Final':'Projected totals'}</span></div><span class="tag ${m.final?'green':'purple'}">${m.final?'FINAL':'UPCOMING'}</span></div>
  <div class="matchup-body"><div class="match-scoreboard"><div class="match-team">${emblem(a)}<div class="team-title">${escapeHTML(a.name)}</div><div class="team-subtitle">${a.id===0?'YOU':escapeHTML(a.manager)}</div><div class="score-pair">${fmt(lhs)}${winner===a.id?'<span style="color:var(--lime)">◆</span>':''}</div></div><div class="versus">VS</div><div class="match-team">${emblem(b)}<div class="team-title">${escapeHTML(b.name)}</div><div class="team-subtitle">${b.id===0?'YOU':escapeHTML(b.manager)}</div><div class="score-pair">${fmt(rhs)}${winner===b.id?'<span style="color:var(--lime)">◆</span>':''}</div></div></div><div class="matchup-progress"><span style="width:${ratio}%"></span><span style="flex:1"></span></div><div class="two-line micro muted"><span>${Math.round(ratio)}% score share</span><span>${100-Math.round(ratio)}% score share</span></div><div class="matchup-bottom"><span>${m.final?'Your lineup was locked for this round.':'Swap starters before simulating this week.'}</span><button class="text-button" data-view="matchups">ALL MATCHUPS ↗</button></div></div></div>`;
}
function activityFeed(){const completed=game.lastSimulatedWeek>0;const events=completed?game.lastEvents:PLAYER_POOL.slice().sort((a,b)=>b.rating-a.rating).slice(0,4).map((p,i)=>({id:p.id,t:i,points:projection(p.id,1),top:[['Projected impact',1,0]]}));return `<div class="panel"><div class="panel-header"><div><strong>${completed?'OPERATION FEED':'SCOUTING REPORT'}</strong><span class="subline">${completed?'Standout performances from the last round':'Top talent to watch this season'}</span></div><span class="tag">${completed?'WEEK '+String(game.lastSimulatedWeek).padStart(2,'0'):'SCOUTING'}</span></div><div class="activity-list">${events.slice(0,4).map((e,i)=>{const p=player(e.id);return `<div class="activity-item"><span class="activity-dot" style="color:${ROLE_INFO[p.role].color}">${ROLE_INFO[p.role].symbol}</span><div class="activity-copy"><strong>${escapeHTML(p.name)}</strong> ${completed?`earned <strong>${fmt(e.points)} pts</strong> for ${escapeHTML(team(e.t).name)}.`:`enters the season as a <strong>${p.rating} OVR</strong> ${ROLE_INFO[p.role].name}.`}<span class="timestamp">${completed?escapeHTML(e.top?.[0]||'Weekly performance'):'PRESEASON SCOUTING'} · ${shortRole(p.role)}</span></div></div>`;}).join('')}</div></div>`;}
function lineupSnippet(){const t=userTeam();return `<div class="panel"><div class="panel-header"><div><strong>YOUR STARTING SIX</strong><span class="subline">Projected points · ${weekName(game.week)}</span></div><button class="text-button" data-view="roster">EDIT LINEUP ↗</button></div><div class="slot-list">${SLOTS.map(slot=>{const pid=t.lineup[slot];const p=player(pid);return `<div class="slot-row"><div class="slot-code">${shortRole(slot)}</div>${p?avatar(p):'<span class="player-avatar">?</span>'}<div style="min-width:0"><div class="player-name">${p?escapeHTML(p.name):'OPEN SLOT'}</div><div class="player-meta">${p?ROLE_INFO[p.role].name:'No eligible starter'}</div></div><div class="slot-score">${pid?fmt(projection(pid,currentWeek())):'0.0'}<small>PROJ</small></div></div>`;}).join('')}</div></div>`;}
function smallStandings(){const rankings=leagueTable().slice(0,5);return `<div class="panel league-table"><div class="panel-header"><div><strong>LEAGUE STANDINGS</strong><span class="subline">Top operations · regular season</span></div><button class="text-button" data-view="leaderboard">FULL TABLE ↗</button></div><table class="table"><thead><tr><th>#</th><th>TEAM</th><th>W-L</th><th>PTS</th></tr></thead><tbody>${rankings.map((r,i)=>`<tr class="${r.id===0?'you':''}"><td><span class="rank">${String(i+1).padStart(2,'0')}</span></td><td><span class="strong">${escapeHTML(team(r.id).name)}</span></td><td>${r.wins}-${r.losses}</td><td class="mono">${fmt(r.pf)}</td></tr>`).join('')}</tbody></table></div>`;}
function renderOverview(){
  const standings=leagueTable(),my=standings.find(x=>x.id===0),rank=ranking(0);
  const cur=game.week<=9?matchForTeam(game.week,0):matchForTeam(9,0);
  const champion=game.results[9]?team(winnerId(game.results[9][0])):null;
  const heroText=game.draft.active?'YOUR DRAFT. <span>YOUR DYNASTY.</span>':champion?'SEASON OVER. <span>LEGACY MADE.</span>':'YOUR OPERATION. <span>YOUR DYNASTY.</span>';
  const heroDesc=game.draft.active?'Your league is on the clock. Draft a team of cyber specialists before the season begins.':champion?`${escapeHTML(champion.name)} is this season’s champion. Start a fresh draft to compete again.`:'Build an elite security roster, outsmart rival teams, and climb to the top of the cyber league.';
  const heroButton=game.draft.active?'<button class="button primary hero-button" data-view="draft">ENTER DRAFT ROOM →</button>':champion?'<button class="button primary hero-button" data-action="start-draft">START NEW SEASON →</button>':`<button class="button primary hero-button" data-action="simulate">${weekName(game.week)==='SEMIFINALS'?'PLAY SEMIFINALS':weekName(game.week)==='CHAMPIONSHIP'?'PLAY CHAMPIONSHIP':'SIMULATE '+weekName(game.week)} →</button>`;
  const heroSvg=`<svg viewBox="0 0 450 250" fill="none" aria-hidden="true"><circle cx="225" cy="123" r="108" stroke="#b7f76a" stroke-width="1" opacity=".2"/><circle cx="225" cy="123" r="83" stroke="#b7f76a" stroke-width="1" opacity=".15"/><circle cx="225" cy="123" r="58" stroke="#b7f76a" stroke-width="1" opacity=".18"/><path d="m225 36 76 44v85l-76 44-76-44V80z" stroke="#b7f76a" stroke-width="3" fill="#b7f76a" fill-opacity=".04"/><path d="m250 87-47 35 47 35" stroke="#b7f76a" stroke-width="10" stroke-linecap="round" stroke-linejoin="round"/><path d="M25 130h104M323 125h106M70 60l76 40M305 151l90 40M88 208l59-44" stroke="#7ebd7e" opacity=".32"/><g fill="#b7f76a"><circle cx="68" cy="60" r="4"/><circle cx="395" cy="191" r="4"/><circle cx="25" cy="130" r="3"/><circle cx="430" cy="125" r="4"/><circle cx="89" cy="208" r="3"/></g></svg>`;
  return `<section class="dashboard-hero"><div class="hero-copy"><div class="eyebrow">WELCOME TO SEASON 01 // COMMAND HQ</div><h1>${heroText}</h1><p>${heroDesc}</p>${heroButton}</div><div class="hero-art">${heroSvg}</div></section>
    <div class="stat-grid">${statCard('YOUR RECORD',`${my.wins} - ${my.losses}`,'Regular season record','target')}${statCard('TOTAL POINTS',fmt(my.pf),'Cumulative scored','bolt')}${statCard('LEAGUE RANK',`#${rank} <span style="font-size:14px;color:var(--low)">/ 8</span>`,'Current standings','trophy','var(--lime)')}${statCard('WEEKLY PROJECTION',fmt(teamScore(userTeam(),currentWeek())),'Current starting lineup','chart')}</div>
    ${game.draft.active?'<div class="banner-message" style="margin-bottom:20px"><div><strong>Your snake draft is underway</strong><p>Head to Draft Room to choose your next operator.</p></div><button class="button primary" data-view="draft">CONTINUE DRAFT</button></div>':''}
    <div class="dashboard-grid">${matchupPanel(cur)}${activityFeed()}</div><div class="bottom-grid">${smallStandings()}${lineupSnippet()}</div>`;
}
function renderRoster(){const t=userTeam();const bench=t.roster.filter(id=>!Object.values(t.lineup).includes(id));const invalid=SLOTS.filter(s=>!validForSlot(t.lineup[s],s));const rows=[...SLOTS.map(slot=>({slot,id:t.lineup[slot],bench:false})),...bench.map((id,i)=>({slot:'bn'+(i+1),id,bench:true}))];
  const content=`<div class="panel"><div class="panel-header"><div><strong>ACTIVE LINEUP</strong><span class="subline">6 starters + ${bench.length} bench players · Select SWAP to rearrange</span></div><span class="tag green">${fmt(teamScore(t,currentWeek()))} PROJECTED</span></div><div class="roster-rows">${rows.map(({slot,id,bench})=>{const p=player(id);return `<div class="roster-row ${bench?'bench':''}"><div class="position">${bench?'BN':shortRole(slot)}</div>${p?avatar(p):'<span class="player-avatar">?</span>'}<div class="identity">${p?`<button class="open-profile" data-player="${id}"><span class="player-name">${escapeHTML(p.name)}</span></button><div class="player-meta">${ROLE_INFO[p.role].name} · ${p.rating} OVR · ${escapeHTML(p.org)}</div>`:'<span class="player-name" style="color:var(--pink)">EMPTY POSITION</span><div class="player-meta">Draft or sign an eligible specialist</div>'}</div><div class="proj"><strong>${id?fmt(projection(id,currentWeek())):'0.0'}</strong><span>PROJ PTS</span></div>${!bench?`<button class="button sm" data-swap="${slot}">SWAP</button>`:`<button class="button sm" data-player="${id}">INFO</button>`}</div>`;}).join('')}</div></div>`;
  let info=`<div class="panel panel-pad"><div class="eyebrow">LINEUP HEALTH</div><h2 class="section-title" style="margin:10px 0 18px">Operation readiness</h2><div class="notice ${invalid.length?'warn':''}">${invalid.length?`<strong>${invalid.length} unfilled or invalid position(s).</strong> Each missing starter scores zero. Find a qualified operator in Free Agents.`:'<strong>All six positions are filled.</strong> Your operation is ready for kickoff.'}</div><div class="divider"></div><div class="compact-line"><span class="muted">Rostered players</span><strong>${t.roster.length} / 8</strong></div><div class="compact-line"><span class="muted">Starting specialists</span><strong>${6-invalid.length} / 6</strong></div><div class="compact-line"><span class="muted">Projected this round</span><strong class="accent">${fmt(teamScore(t,currentWeek()))} pts</strong></div><div class="compact-line"><span class="muted">Available free agents</span><strong>${availablePlayers().length}</strong></div><div style="margin-top:22px"><button class="button primary" style="width:100%" data-view="market">EXPLORE FREE AGENTS →</button></div></div>`;
  const roleLegend=`<div class="panel" style="margin-top:17px"><div class="panel-header"><strong>STARTING POSITIONS</strong></div><div class="panel-pad" style="padding-top:8px">${SLOTS.map(role=>`<div class="compact-line"><span class="role-key"><span class="role-circle" style="color:${ROLE_INFO[role].color};background:${ROLE_INFO[role].color}19">${ROLE_INFO[role].symbol}</span>${ROLE_INFO[role].name}</span><span class="muted">${shortRole(role)}</span></div>`).join('')}</div></div>`;
  return heading('YOUR SQUAD','My Roster','Manage your starting six. Only starters earn points each week.',`<button class="button ghost" data-view="draft">DRAFT ROOM</button><button class="button primary" data-action="simulate" ${game.draft.active||game.week>9?'disabled':''}>${game.week>9?'SEASON COMPLETE':'PLAY '+weekName(game.week)} →</button>`)+`<div class="roster-main"><div>${content}</div><div>${info}${roleLegend}</div></div>`;
}
function startDraft(){game={version:VERSION,teams:freshTeams(),week:1,results:{},lastSimulatedWeek:0,lastEvents:[],draft:{active:true,complete:false,pick:0,picks:[]}};advanceBots();save();navigate('draft');toast('New snake draft started. You are on the clock!');}
function draftOrder(index){let round=Math.floor(index/8),offset=index%8;return round%2===0?offset:7-offset;}
function draftBotChoice(t){let p=availablePlayers();const missing=ROLES.filter(role=>!t.roster.some(id=>player(id).role===role));if(missing.length){const candidates=p.filter(x=>missing.includes(x.role));candidates.sort((a,b)=>b.rating-a.rating||a.id-b.id);return candidates[0]?.id;}p.sort((a,b)=>b.rating-a.rating||a.id-b.id);return p[0]?.id;}
function advanceBots(){while(game.draft.active&&game.draft.pick<64&&draftOrder(game.draft.pick)!==0){const tId=draftOrder(game.draft.pick),id=draftBotChoice(team(tId));if(!id)break;recordPick(tId,id);}if(game.draft.pick>=64)completeDraft();}
function recordPick(tid,id){const t=team(tid);if(!t||!player(id)||t.roster.includes(id)||!availablePlayers().some(p=>p.id===id))return false;t.roster.push(id);game.draft.picks.push({pick:game.draft.pick+1,team:tid,player:id});game.draft.pick++;t.lineup=assignLineup(t.roster);return true;}
function draftPlayer(id){if(!game.draft.active)return toast('Start a new draft first.',true);if(draftOrder(game.draft.pick)!==0)return toast('The bot teams are still drafting.',true);if(!recordPick(0,id))return toast('That operator is not available.',true);advanceBots();if(game.draft.pick>=64)completeDraft();save();render();toast(game.draft.active?`${player(id).name} drafted! Next pick is ready.`:'Draft complete! Your roster is ready.');}
function completeDraft(){game.draft.active=false;game.draft.complete=true;game.teams.forEach(t=>t.lineup=assignLineup(t.roster));game.week=1;}
function draftPlayerCard(p){return `<div class="player-card"><div class="player-card-head"><div><div class="role-name" style="color:${ROLE_INFO[p.role].color}">${shortRole(p.role)} / ${ROLE_INFO[p.role].name.toUpperCase()}</div><div class="player-card-title">${escapeHTML(p.name)}</div><div class="handle">${escapeHTML(p.handle)} · ${escapeHTML(p.org)}</div></div>${avatar(p)}</div><div class="player-card-ratings"><div class="metric"><label>OVERALL</label><strong>${p.rating}</strong></div><div class="metric"><label>PROJECTION</label><strong>${fmt(projection(p.id,currentWeek()))}</strong></div><div class="metric"><label>TREND</label><strong style="color:${p.trend>=0?'var(--lime)':'var(--pink)'}">${p.trend>0?'+':''}${p.trend}</strong></div></div><div class="player-card-foot"><button class="button primary" data-pick="${p.id}">DRAFT OPERATOR →</button><button class="button" data-player="${p.id}">PROFILE</button></div></div>`;}
function filters(){return `<div class="market-controls"><div class="search-wrap"><input id="market-search" type="search" placeholder="Search operators, handles, organizations..." value="${escapeHTML(marketQuery)}" autocomplete="off" aria-label="Search players" /></div><select id="market-role" aria-label="Filter by role"><option value="all" ${marketRole==='all'?'selected':''}>All Positions</option>${ROLES.map(role=>`<option value="${role}" ${marketRole===role?'selected':''}>${ROLE_INFO[role].name}</option>`).join('')}</select><select id="market-sort" aria-label="Sort players"><option value="rating" ${marketSort==='rating'?'selected':''}>Highest Rated</option><option value="projection" ${marketSort==='projection'?'selected':''}>Most Projected</option><option value="name" ${marketSort==='name'?'selected':''}>Name A–Z</option></select></div>`;}
function filteredPlayers(){const q=marketQuery.trim().toLowerCase();let ps=availablePlayers().filter(p=>(marketRole==='all'||p.role===marketRole)&&(!q||[p.name,p.handle,p.org,ROLE_INFO[p.role].name].some(x=>x.toLowerCase().includes(q))));ps.sort((a,b)=>marketSort==='name'?a.name.localeCompare(b.name):marketSort==='projection'?projection(b.id,currentWeek())-projection(a.id,currentWeek())||b.rating-a.rating:b.rating-a.rating||a.id-b.id);return ps;}
function renderDraftList(){const list=document.getElementById('player-list');if(!list)return;const arr=filteredPlayers();list.innerHTML=arr.length?arr.map(draftPlayerCard).join(''):'<div class="app-empty">No available operators match that search.</div>';const count=document.getElementById('player-count');if(count)count.textContent=`${arr.length} AVAILABLE`;}
function renderDraft(){
  if(!game.draft.active){return heading('THE WAR ROOM','Draft Room','Build your squad in an eight-team, eight-round snake draft.',`<button class="button primary" data-action="start-draft">START NEW SNAKE DRAFT →</button>`)+`<div class="howto-intro"><div class="eyebrow">SCOUT. SELECT. DOMINATE.</div><h2>Your next dynasty starts here.</h2><p>Every team drafts 8 cyber specialists: aim to fill SOC, RED, DFIR, INTEL, ENG, and FLEX, with two players on the bench. In snake format, the pick order reverses every round. Rivals draft automatically.</p><div class="inline-flex" style="margin-top:19px;flex-wrap:wrap"><span class="tag green">8 TEAMS</span><span class="tag green">8 ROUNDS</span><span class="tag green">64 PICKS</span><span class="tag green">SNAKE FORMAT</span></div><div style="margin-top:23px"><button class="button primary" data-action="start-draft">CREATE A NEW DRAFT →</button></div></div><div class="grid-2"><div class="panel panel-pad"><div class="eyebrow">HOW IT WORKS</div><h2 class="section-title" style="margin:12px 0">The draft format</h2><p class="muted small" style="line-height:1.8">You pick first in rounds 1, 3, 5, and 7; last in rounds 2, 4, 6, and 8. Choose talent wisely: a complete starting lineup matters as much as star power.</p></div><div class="panel panel-pad"><div class="eyebrow">CURRENT ROSTER</div><h2 class="section-title" style="margin:12px 0">Your existing team is saved</h2><p class="muted small" style="line-height:1.8">Starting a new draft resets standings, weekly scores, and rosters for every team. Export your existing game from Settings if you want a backup.</p></div></div>`;}
  const picks=game.draft.picks;const round=Math.floor(game.draft.pick/8)+1;const yours=userTeam().roster;
  return heading('THE WAR ROOM','Live Draft','The clock is yours. Pick the next specialist for your squad.',`<span class="tag green">${game.draft.pick}/64 PICKS MADE</span>`)+`<div class="draft-banner"><div><div class="eyebrow">YOU ARE ON THE CLOCK</div><div class="on-clock">ROUND ${round} <span>· PICK ${game.draft.pick+1}</span></div><div class="banner-desc">Select an available specialist below. Bot teams pick immediately after you.</div></div><div style="text-align:right"><div class="eyebrow">NEXT SELECTION</div><div class="large-pick">${Math.min(64,game.draft.pick+1)}/64</div></div></div><div class="draft-layout"><div><div class="section-heading"><div><h2>Available operators</h2><p>Sort by overall or upcoming performance</p></div><span id="player-count" class="tag">${availablePlayers().length} AVAILABLE</span></div>${filters()}<div id="player-list" class="player-grid">${filteredPlayers().map(draftPlayerCard).join('')}</div></div><div class="draft-side"><div class="panel"><div class="panel-header"><div><strong>YOUR DRAFT BOARD</strong><span class="subline">${yours.length} / 8 spots filled</span></div></div><div class="slot-list">${yours.length?yours.map(id=>{const p=player(id);return `<div class="slot-row">${avatar(p)}<div style="flex:1"><div class="player-name">${escapeHTML(p.name)}</div><div class="player-meta">${shortRole(p.role)} · ${p.rating} OVR</div></div></div>`;}).join(''):'<div class="empty-state">No picks yet. You are first on the board.</div>'}</div></div><div class="panel"><div class="panel-header"><strong>RECENT PICKS</strong></div><div class="slot-list">${picks.slice(-6).reverse().map(p=>`<div class="compact-line"><span class="muted">#${String(p.pick).padStart(2,'0')} · ${escapeHTML(team(p.team).name)}</span><strong>${escapeHTML(player(p.player).name)}</strong></div>`).join('')||'<div class="empty-state">Draft picks appear here.</div>'}</div></div></div></div>`;
}
function renderMarket(){const inDraft=game.draft.active;return heading('SCOUTING DEPARTMENT','Free Agents','Spot hidden talent, sign replacements, and optimize your lineup.',`<span class="tag green">${availablePlayers().length} AVAILABLE</span>`)+`${inDraft?'<div class="notice warn" style="margin-bottom:20px">Finish your draft before signing free agents.</div>':''}<div class="section-heading"><div><h2>Available talent</h2><p>Signing a player requires releasing someone on your current roster.</p></div><span id="player-count" class="tag">${filteredPlayers().length} AVAILABLE</span></div>${filters()}<div id="player-list" class="player-grid">${filteredPlayers().map(p=>`<div class="player-card"><div class="player-card-head"><div><div class="role-name" style="color:${ROLE_INFO[p.role].color}">${shortRole(p.role)} / ${ROLE_INFO[p.role].name.toUpperCase()}</div><div class="player-card-title">${escapeHTML(p.name)}</div><div class="handle">${escapeHTML(p.handle)} · ${escapeHTML(p.org)}</div></div>${avatar(p)}</div><div class="player-card-ratings"><div class="metric"><label>OVERALL</label><strong>${p.rating}</strong></div><div class="metric"><label>PROJECTION</label><strong>${fmt(projection(p.id,currentWeek()))}</strong></div><div class="metric"><label>TREND</label><strong style="color:${p.trend>=0?'var(--lime)':'var(--pink)'}">${p.trend>0?'+':''}${p.trend}</strong></div></div><div class="player-card-foot"><button class="button primary" data-add="${p.id}" ${inDraft?'disabled':''}>SIGN PLAYER →</button><button class="button" data-player="${p.id}">PROFILE</button></div></div>`).join('')||'<div class="app-empty">No free agents match your filters.</div>'}</div>`;}
function renderMarketList(){const list=document.getElementById('player-list');if(!list)return;const arr=filteredPlayers();const inDraft=game.draft.active;list.innerHTML=arr.length?arr.map(p=>`<div class="player-card"><div class="player-card-head"><div><div class="role-name" style="color:${ROLE_INFO[p.role].color}">${shortRole(p.role)} / ${ROLE_INFO[p.role].name.toUpperCase()}</div><div class="player-card-title">${escapeHTML(p.name)}</div><div class="handle">${escapeHTML(p.handle)} · ${escapeHTML(p.org)}</div></div>${avatar(p)}</div><div class="player-card-ratings"><div class="metric"><label>OVERALL</label><strong>${p.rating}</strong></div><div class="metric"><label>PROJECTION</label><strong>${fmt(projection(p.id,currentWeek()))}</strong></div><div class="metric"><label>TREND</label><strong style="color:${p.trend>=0?'var(--lime)':'var(--pink)'}">${p.trend>0?'+':''}${p.trend}</strong></div></div><div class="player-card-foot"><button class="button primary" data-add="${p.id}" ${inDraft?'disabled':''}>SIGN PLAYER →</button><button class="button" data-player="${p.id}">PROFILE</button></div></div>`).join(''):'<div class="app-empty">No available operators match that search.</div>';const count=document.getElementById('player-count');if(count)count.textContent=`${arr.length} AVAILABLE`;}
function renderMatchups(){const w=selectedWeek>Math.min(game.week,9)?currentWeek():selectedWeek;const final=!!game.results[w];const pairs=final?game.results[w].map(r=>[r.a,r.b]):getPairs(w);const isCurrent=w===game.week;return heading('THE BATTLEGROUND','Matchups','Head-to-head showdowns. Your starting six determines your score.',`<button class="button primary" data-action="simulate" ${game.draft.active||game.week>9?'disabled':''}>${game.week>9?'SEASON COMPLETE':'PLAY '+weekName(game.week)} →</button>`)+`<div class="section-heading"><div><h2>${weekName(w)} ${final?'· Final':'· Projections'}</h2><p>${w<=7?'Regular season · Four head-to-head matches':w===8?'Top four battle for a championship berth':'Championship game and third-place playoff'}</p></div><div class="schedule-controls"><select id="week-select" aria-label="Select week">${Array.from({length:Math.min(game.week,9)},(_,i)=>i+1).map(week=>`<option value="${week}" ${week===w?'selected':''}>${weekName(week)}</option>`).join('')}</select></div></div>${pairs.length?`<div class="matchup-grid">${pairs.map(([a,b],index)=>{const m=final?game.results[w][index]:{a,b,scoreA:teamScore(team(a),w),scoreB:teamScore(team(b),w)};const win=final?winnerId(m):null;return `<div class="panel matchup-card"><div class="matchup-top"><span>${w===9?(index===0?'CHAMPIONSHIP':'THIRD PLACE'):`MATCH ${String(index+1).padStart(2,'0')}`}</span><span class="tag ${final?'green':''}">${final?'FINAL':'PROJECTION'}</span></div><div class="contestant">${miniTeam(team(a))}<strong class="${win===a?'winner':''}">${fmt(m.scoreA)}</strong></div><div class="divider"></div><div class="contestant">${miniTeam(team(b))}<strong class="${win===b?'winner':''}">${fmt(m.scoreB)}</strong></div>${a===0||b===0?'<div class="tag green" style="margin-top:9px">YOUR MATCHUP</div>':''}</div>`;}).join('')}</div>`:`<div class="app-empty">This playoff round will unlock after the previous round finishes.</div>`}${game.week>9?`<div class="banner-message"><div><strong>THE CHAMPION: ${escapeHTML(team(winnerId(game.results[9][0])).name)}</strong><p>Another season awaits. Create a new draft to defend or chase the title.</p></div><button class="button primary" data-action="start-draft">NEW SEASON</button></div>`:''}`;}
function renderLeaderboard(){const rankings=leagueTable(),leader=rankings[0],my=rankings.find(x=>x.id===0);return heading('LEAGUE INTELLIGENCE','Leaderboard','Eight operations. One cybersecurity dynasty.',`<span class="tag green">SEASON 01</span>`)+`<div class="leaderboard-stats"><div class="leaderboard-card"><div class="title">TOP OPERATION</div><div class="value" style="font-size:20px;margin-top:15px">${escapeHTML(team(leader.id).name)}</div><div class="muted small" style="margin-top:7px">${leader.wins} wins · ${fmt(leader.pf)} points</div></div><div class="leaderboard-card"><div class="title">YOUR PLACEMENT</div><div class="value accent">#${ranking(0)} <span class="muted" style="font-size:15px">/ 8</span></div><div class="muted small" style="margin-top:7px">${my.wins}W / ${my.losses}L</div></div><div class="leaderboard-card"><div class="title">GAMES PLAYED</div><div class="value">${Math.min(game.lastSimulatedWeek,7)} <span class="muted" style="font-size:15px">/ 7</span></div><div class="muted small" style="margin-top:7px">${game.lastSimulatedWeek>7?'Postseason underway':'Regular season rounds'}</div></div></div><div class="panel"><div class="panel-header"><div><strong>REGULAR SEASON STANDINGS</strong><span class="subline">Ranked by wins, then total points</span></div><span class="tag">TOP 4 → PLAYOFFS</span></div><div style="overflow-x:auto"><table class="table ranking-table"><thead><tr><th style="width:65px">RANK</th><th>TEAM</th><th>RECORD</th><th>PF</th><th>PA</th><th>DIFF</th></tr></thead><tbody>${rankings.map((x,i)=>{const diff=x.pf-x.pa;return `<tr class="${x.id===0?'you':''}"><td><span class="rank-medal ${i===0?'first':''}">${String(i+1).padStart(2,'0')}</span></td><td>${miniTeam(team(x.id))}</td><td><strong class="strong">${x.wins}-${x.losses}</strong></td><td class="mono">${fmt(x.pf)}</td><td class="mono">${fmt(x.pa)}</td><td class="mono ${diff>=0?'positive':''}">${diff>0?'+':''}${fmt(diff)}</td></tr>`;}).join('')}</tbody></table></div></div><div class="notice" style="margin-top:18px">After Week 7, the top four teams advance. Seeds #1 and #4 face off, as do #2 and #3. Winners play in the championship.</div>`;}
const SCORE_ROWS = [
  ['SOC','Confirmed detection','+6'],['SOC','Proactive hunt','+4'],['SOC','False positive','−2'],
  ['RED','Validated finding','+7'],['RED','Critical discovery','+10'],['RED','Quality write-up','+3'],
  ['DFIR','Incident contained','+8'],['DFIR','Recovery action','+4'],['DFIR','Missed containment','−6'],
  ['INTEL','Actionable report','+5'],['INTEL','Verified indicator','+2'],['INTEL','Threat brief','+3'],
  ['ENG','Hardening fix','+4'],['ENG','Critical patch','+6'],['ENG','Failed change','−3']
];
function renderHowto(){return heading('THE FIELD MANUAL','How to Play','Everything you need to run a winning cyber operation.',`<button class="button primary" data-view="draft">OPEN DRAFT ROOM →</button>`)+`<div class="howto-intro"><div class="eyebrow">THE OBJECTIVE</div><h2>Fantasy football mechanics. Pure cybersecurity.</h2><p>Instead of quarterbacks and running backs, you draft blue-team defenders, red-teamers, incident responders, threat intelligence analysts, and security engineers. A fictional weekly operation simulates their performance. Build the strongest starting six to outscore your opponent.</p><span class="tag green">FICTIONAL PLAYERS</span> <span class="tag green">SIMULATED SECURITY EVENTS</span> <span class="tag green">NO REAL-WORLD BREACH DATA</span></div><div class="steps-grid"><div class="step-card"><div class="step-number">01</div><h3>Draft your specialists</h3><p>Snake draft: 8 teams, 8 rounds, 64 picks. Each team gets 8 operators, including 2 bench spots.</p></div><div class="step-card"><div class="step-number">02</div><h3>Set your starting six</h3><p>One SOC, RED, DFIR, INTEL, ENG, plus one FLEX. Only eligible starters score weekly points.</p></div><div class="step-card"><div class="step-number">03</div><h3>Win the championship</h3><p>Seven regular-season matches decide the top four. Semifinals happen in Week 8; Week 9 crowns a champion.</p></div></div><div class="grid-2"><div class="panel"><div class="panel-header"><div><strong>THE SCORING SYSTEM</strong><span class="subline">Points earned per simulated achievement</span></div></div><table class="table scoring-table"><thead><tr><th>ROLE</th><th>ACTIVITY</th><th>POINTS</th></tr></thead><tbody>${SCORE_ROWS.map(([role,activity,pts])=>`<tr><td><span class="tag">${role}</span></td><td>${activity}</td><td>${pts}</td></tr>`).join('')}</tbody></table></div><div><div class="panel panel-pad"><div class="eyebrow">POSITION RULES</div><h2 class="section-title" style="margin:10px 0 18px">Your six starters</h2>${SLOTS.map(role=>`<div class="compact-line"><span class="role-key"><span class="role-circle" style="color:${ROLE_INFO[role].color};background:${ROLE_INFO[role].color}19">${ROLE_INFO[role].symbol}</span>${ROLE_INFO[role].name}</span><strong>${shortRole(role)}</strong></div>`).join('')}<div class="notice" style="margin-top:20px">FLEX accepts any specialist. Your bench players score zero until moved into a starting spot. Missing positions also score zero.</div></div><div class="panel panel-pad" style="margin-top:17px"><div class="eyebrow">FAIR PLAY</div><h2 class="section-title" style="margin:10px 0 15px">How simulation works</h2><p class="muted small" style="line-height:1.8">Results are deterministic per player and week, with performance influenced by overall rating. All teams use the same scoring rules. These are imagined cyber activities, not data from employers, live breaches, CTF events, or actual professionals.</p><p class="muted small" style="line-height:1.8">A browser save tracks your season. A published link lets others play their own independent leagues; synchronized multiplayer and accounts are not included in this version.</p></div></div></div>`;}
function renderSettings(){return heading('SYSTEM CONFIGURATION','League Settings','Rename your operation, back up progress, or launch a new season.')+`<div class="settings-wrap"><div class="panel panel-pad"><div class="eyebrow">FRANCHISE IDENTITY</div><h2 class="section-title" style="margin:10px 0 9px">Customize your team</h2><p class="muted small">This name appears in the standings, scoreboards, and matchups.</p><div class="form-group"><label class="field-label" for="team-name">TEAM NAME</label><input id="team-name" maxlength="26" value="${escapeHTML(userTeam().name)}" placeholder="Enter your team name" /></div><button class="button primary" data-action="save-name">SAVE TEAM NAME</button></div><div class="panel panel-pad" style="margin-top:18px"><div class="eyebrow">YOUR GAME DATA</div><h2 class="section-title" style="margin:10px 0 8px">Save and transfer</h2><p class="muted small" style="line-height:1.8">Progress is saved automatically in this browser. Export a JSON file before switching devices or clearing browser data. Importing restores your previous season.</p><div class="settings-actions" style="margin-top:18px"><button class="button" data-action="export">↓ EXPORT SAVE</button><button class="button" data-action="import">↑ IMPORT SAVE</button><button class="button" data-action="share">↗ SHARE RESULTS</button></div></div><div class="panel panel-pad" style="margin-top:18px"><div class="eyebrow">SEASON CONTROL</div><h2 class="section-title" style="margin:10px 0 8px">Reset the league</h2><p class="muted small" style="line-height:1.8">Restart the draft, clear all scores, and create fresh rosters for the eight teams. Your old league cannot be recovered unless you exported a save.</p><button class="button danger" style="margin-top:16px" data-action="reset-confirm">RESET & START SNAKE DRAFT</button></div><div class="muted-card" style="margin-top:18px">Cipher League v1.0.0 · Browser-based single-player fantasy simulator · No real-world cybersecurity outcomes or shared multiplayer state. All player names, organizations, and events are fictional.</div></div>`;}
function modal(title,body,foot='',wide=false){const root=document.getElementById('overlay-root');root.innerHTML=`<div class="modal-backdrop" data-close-backdrop="true"><div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${escapeHTML(title)}"><div class="modal-header"><h2>${escapeHTML(title)}</h2><button class="modal-close" data-action="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}</div></div>`;}
function closeModal(){document.getElementById('overlay-root').innerHTML='';}
function openProfile(id){const p=player(id);if(!p)return;const maxWeek=Math.min(game.lastSimulatedWeek,9);const details=scoreDetails(id,currentWeek());const history=Array.from({length:maxWeek},(_,i)=>({w:i+1,score:scoreDetails(id,i+1).points}));const avg=history.length?history.reduce((sum,x)=>sum+x.score,0)/history.length:projection(id,1);const owned=game.teams.find(t=>t.roster.includes(id));const breakdown=`<div class="panel" style="margin-top:17px"><div class="panel-header"><strong>${game.lastSimulatedWeek?`WEEK ${game.lastSimulatedWeek} PERFORMANCE`:'SAMPLE SCORING BREAKDOWN'}</strong></div><div style="padding:5px 20px">${(game.lastSimulatedWeek?scoreDetails(id,game.lastSimulatedWeek):details).events.map(([name,qty,mult])=>`<div class="compact-line"><span class="muted">${escapeHTML(name)} · ${qty} × ${mult}</span><strong class="${mult<0?'down':'up'}">${qty*mult>0?'+':''}${qty*mult}</strong></div>`).join('')}</div></div>`;
  modal('OPERATOR PROFILE',`<div class="profile-hero">${avatar(p)}<div><div class="eyebrow">${ROLE_INFO[p.role].name.toUpperCase()} · ${escapeHTML(p.org)}</div><h2>${escapeHTML(p.name)}</h2><p>${escapeHTML(p.handle)}</p></div></div><div class="stat-row"><div><small>OVERALL RATING</small><strong>${p.rating}</strong></div><div><small>WEEKLY PROJ</small><strong>${fmt(projection(id,currentWeek()))}</strong></div><div><small>AVERAGE SCORE</small><strong>${fmt(avg)}</strong></div></div><div class="divider"></div><div class="compact-line"><span class="muted">Roster status</span><strong>${owned?escapeHTML(owned.name):'FREE AGENT'}</strong></div><div class="compact-line"><span class="muted">Specialty</span><strong>${ROLE_INFO[p.role].name}</strong></div>${breakdown}<div class="muted small" style="margin-top:16px">All performance results are fictional and simulated.</div>`);
}
function openSwap(slot){const t=userTeam();const current=t.lineup[slot];const eligible=t.roster.filter(id=>id!==current&&validForSlot(id,slot)&&canSwap(slot,id));if(!eligible.length)return toast('No eligible substitutes available. Sign a free agent.',true);modal('SWAP STARTER',`<p class="muted small">Choose an eligible operator for the ${shortRole(slot)} position. Your lineup changes immediately.</p><div style="margin-top:17px">${eligible.map(id=>{const p=player(id);const starting=Object.entries(t.lineup).find(([,pid])=>pid===id);return `<button class="choice" data-choose-swap="${slot}:${id}">${avatar(p)}<span style="flex:1"><strong>${escapeHTML(p.name)}</strong><span class="muted small" style="display:block;margin-top:3px">${shortRole(p.role)} · ${p.rating} OVR · ${starting?'Starting '+shortRole(starting[0]):'BENCH'}</span></span><span class="chip">${fmt(projection(id,currentWeek()))} PTS</span></button>`;}).join('')}</div>`);}
function canSwap(slot,id){if(!validForSlot(id,slot))return false;const current=userTeam().lineup[slot];const oldSlot=Object.keys(userTeam().lineup).find(s=>userTeam().lineup[s]===id);return !oldSlot||!current||validForSlot(current,oldSlot);}
function swap(slot,id){if(!SLOTS.includes(slot)||!userTeam().roster.includes(id)||!canSwap(slot,id))return toast('That swap is not valid for the lineup.',true);const t=userTeam();const oldId=t.lineup[slot];const fromSlot=Object.keys(t.lineup).find(s=>t.lineup[s]===id);t.lineup[slot]=id;if(fromSlot)t.lineup[fromSlot]=oldId||null;save();closeModal();render();toast(`${player(id).name} is now your ${shortRole(slot)} starter.`);}
function openAdd(id){if(game.draft.active)return toast('Finish the draft before signing free agents.',true);const p=player(id);if(!p||!availablePlayers().some(x=>x.id===id))return toast('Player is no longer available.',true);const roster=userTeam().roster;modal('SIGN FREE AGENT',`<p class="muted small">To add <strong style="color:white">${escapeHTML(p.name)} (${shortRole(p.role)})</strong>, choose one of your players to release. The new signing will take that roster spot.</p><div style="margin-top:17px">${roster.map(dropId=>{const x=player(dropId);return `<button class="choice" data-confirm-drop="${id}:${dropId}">${avatar(x)}<span style="flex:1"><strong>${escapeHTML(x.name)}</strong><span class="muted small" style="display:block;margin-top:3px">${shortRole(x.role)} · ${x.rating} OVR</span></span><span class="tag red">RELEASE</span></button>`;}).join('')}</div>`);}
function signPlayer(addId,dropId){const t=userTeam();if(!availablePlayers().some(p=>p.id===addId)||!t.roster.includes(dropId))return toast('That transaction is no longer valid.',true);const dropSlot=Object.keys(t.lineup).find(s=>t.lineup[s]===dropId);t.roster[t.roster.indexOf(dropId)]=addId;if(dropSlot){t.lineup[dropSlot]=validForSlot(addId,dropSlot)?addId:null;}
  // Repair now-empty core positions with eligible bench operators where possible.
  for(const slot of SLOTS){if(!t.lineup[slot]){const eligible=t.roster.filter(id=>validForSlot(id,slot)&&!Object.values(t.lineup).includes(id)).sort((a,b)=>player(b).rating-player(a).rating);t.lineup[slot]=eligible[0]||null;}}
  save();closeModal();render();toast(`Signed ${player(addId).name}. Released ${player(dropId).name}.`);
}
function toast(msg,error=false){const root=document.getElementById('toast-root');const element=document.createElement('div');element.className='toast'+(error?' error':'');element.textContent=msg;root.append(element);setTimeout(()=>element.remove(),4600);}
function downloadSave(){const blob=new Blob([JSON.stringify(game,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='cipher-league-save.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Save file exported.');}
function shareResults(){const s=leagueTable().find(x=>x.id===0);const text=`🔐 CIPHER LEAGUE · SEASON 01\n${userTeam().name}: ${s.wins}-${s.losses} · ${fmt(s.pf)} pts · Rank #${ranking(0)}/8\nPlay fantasy cybersecurity: ${location.href.split('#')[0]}`;if(navigator.share){navigator.share({title:'Cipher League season',text}).catch(()=>{});}else if(navigator.clipboard){navigator.clipboard.writeText(text).then(()=>toast('Season summary copied!')).catch(()=>toast('Clipboard unavailable in this browser.',true));}else toast('Clipboard unavailable in this browser.',true);}
function saveTeamName(){const input=document.getElementById('team-name');if(!input)return;const name=input.value.trim().replace(/\s+/g,' ');if(name.length<3||name.length>26)return toast('Team names must be 3–26 characters.',true);game.teams[0].name=name;save();render();toast('Your team has been renamed.');}
function action(name){
  if(name==='simulate')playWeek();
  if(name==='start-draft'||name==='reset-confirm')modal('START A NEW DRAFT?',`<p class="muted small" style="line-height:1.8">Your current rosters, standings, and weekly results will be cleared. This cannot be undone. Export a save first if you want a backup.</p>`,`<button class="button ghost" data-action="close">CANCEL</button><button class="button danger" data-action="reset-now">START NEW DRAFT</button>`);
  if(name==='reset-now'){closeModal();startDraft();}
  if(name==='close')closeModal();
  if(name==='save-name')saveTeamName();
  if(name==='export')downloadSave();
  if(name==='import')document.getElementById('import-file').click();
  if(name==='share')shareResults();
}
function handleMarketChange(){const search=document.getElementById('market-search');const role=document.getElementById('market-role');const sort=document.getElementById('market-sort');marketQuery=search?.value||'';marketRole=role?.value||'all';marketSort=sort?.value||'rating';if(view==='draft')renderDraftList();else renderMarketList();}
document.addEventListener('click',e=>{
  const target=e.target;
  if(target.id==='mobile-menu'){document.getElementById('sidebar').classList.add('is-open');document.getElementById('mobile-scrim').classList.add('is-open');return;}
  if(target.id==='mobile-scrim'){closeNav();return;}
  if(target.matches('.modal-backdrop')){closeModal();return;}
  const v=target.closest('[data-view]');if(v){navigate(v.dataset.view);return;}
  const a=target.closest('[data-action]');if(a){action(a.dataset.action);return;}
  const p=target.closest('[data-player]');if(p){openProfile(Number(p.dataset.player));return;}
  const swapButton=target.closest('[data-swap]');if(swapButton){openSwap(swapButton.dataset.swap);return;}
  const swapChoice=target.closest('[data-choose-swap]');if(swapChoice){const [slot,id]=swapChoice.dataset.chooseSwap.split(':');swap(slot,Number(id));return;}
  const add=target.closest('[data-add]');if(add){openAdd(Number(add.dataset.add));return;}
  const confirm=target.closest('[data-confirm-drop]');if(confirm){const [addId,dropId]=confirm.dataset.confirmDrop.split(':').map(Number);signPlayer(addId,dropId);return;}
  const pick=target.closest('[data-pick]');if(pick){draftPlayer(Number(pick.dataset.pick));return;}
});
document.addEventListener('input',e=>{if(e.target.id==='market-search')handleMarketChange();});
document.addEventListener('change',e=>{if(['market-role','market-sort'].includes(e.target.id))handleMarketChange();if(e.target.id==='week-select'){selectedWeek=Number(e.target.value);render();}});
document.getElementById('import-file').addEventListener('change',async(e)=>{const file=e.target.files?.[0];if(!file)return;try{const loaded=JSON.parse(await file.text());if(!validateSave(loaded))throw new Error('Invalid or incompatible save');game=loaded;save();closeModal();navigate('overview');toast('Your Cipher League save has been restored.');}catch(error){toast('Unable to import this game save.',true);}e.target.value='';});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeNav();}});
window.addEventListener('hashchange',()=>{const id=location.hash.replace('#','');if(NAV.some(x=>x[0]===id)&&id!==view){view=id;render();}});
if(NAV.some(x=>x[0]===location.hash.replace('#','')))view=location.hash.slice(1);
selectedWeek=currentWeek();render();
